package net.civeira.phylax.features.access.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SamlIdpIdpCertVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property saml idp idp cert of tenant login provider ")
  void test_saml_idp_idp_cert_v_o_builder() {
    Assertions.assertFalse(SamlIdpIdpCertVO.nullValue().getSamlIdpIdpCert().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SamlIdpIdpCertVO.tryFrom(null).getSamlIdpIdpCert().isPresent(),
        "With a null value, no present result");
    Assertions.assertThrows(ConstraintException.class,
        () -> SamlIdpIdpCertVO.tryFrom(Integer.valueOf(1)));
    Assertions.assertEquals("file_1",
        SamlIdpIdpCertVO.from("file_1").getSamlIdpIdpCert().orElse(null));
    Assertions.assertEquals("[" + "file_1" + "]",
        SamlIdpIdpCertVO.fromTemporal("file_1").toString());
    Assertions.assertFalse(SamlIdpIdpCertVO.from("file_1").isSamlIdpIdpCertTemporal());
    Assertions.assertTrue(SamlIdpIdpCertVO.fromTemporal("file_1").isSamlIdpIdpCertTemporal());
    Assertions.assertEquals("[" + "file_1" + "]", SamlIdpIdpCertVO.from("file_1").toString());
    Assertions.assertFalse(SamlIdpIdpCertVO.tryFrom("1").isSamlIdpIdpCertTemporal());
    Assertions.assertTrue(SamlIdpIdpCertVO.tryFrom("temp://1").isSamlIdpIdpCertTemporal());
  }
}
